const state={lang:'zh',regime:'CN',page:'search',query:'',spec:'',showSpec:false,searched:false,filters:{category:'all',kind:'all',direction:'all'},offset:0,result:null,scenario:null,answers:{},fiberInput:{},fiberCalculation:null,evaluation:null,menu:false,detail:null,detailTab:'overview'};
